import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmInfProf = () => {
  const { id } = useParams();
  const [professor, setProfessor] = useState(null);
  const [listaCursos, setListaCursos] = useState([]);
  const [cursosSelecionados, setCursosSelecionados] = useState([]);

  useEffect(() => {
    const fetchProfessor = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/professores/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setProfessor(dados);
          setCursosSelecionados(dados.cursos || []);
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    const fetchCursos = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setListaCursos(dados);
        }
      } catch (error) {
        console.error("Erro na requisição de cursos:", error);
      }
    };

    fetchProfessor();
    fetchCursos();
  }, [id]);

  const handleCursoChange = (index, value) => {
    const novosCursos = [...cursosSelecionados];
    novosCursos[index] = value;
    setCursosSelecionados(novosCursos);
  };

  const handleAddCurso = () => {
    setCursosSelecionados([...cursosSelecionados, ""]);
  };

  const salvarCursos = async () => {
    try {
      const resposta = await fetch(`http://localhost:5000/professores/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ cursos: cursosSelecionados }),
      });

      if (resposta.ok) {
        alert("Cursos atualizados com sucesso!");
      }
    } catch (error) {
      console.error("Erro ao salvar cursos:", error);
    }
  };

  if (!professor) return <p className="text-center mt-4">Carregando...</p>;

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistcurso">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informação do Professor</h4>
          <p>
            <strong>{professor.nome}</strong>
          </p>
          <p>{professor.email}</p>
          <p>{professor.morada}</p>
          <p>{professor.contacto}</p>
        </div>

        <div className="w-50 ps-4">
          <label className="fw-bold">Cursos que Leciona</label>
          {cursosSelecionados.map((curso, index) => (
            <div key={index} className="input-group mb-2">
              <input
                type="text"
                className="form-control"
                value={curso}
                onChange={(e) => handleCursoChange(index, e.target.value)}
              />
            </div>
          ))}
          <button
            className="btn btn-outline-secondary mt-2"
            onClick={handleAddCurso}
          >
            +
          </button>

          <div className="d-flex justify-content-between mt-3">
            <button
              className="btn btn-danger"
              onClick={() => setCursosSelecionados(professor.cursos || [])}
            >
              Cancelar
            </button>
            <button className="btn btn-primary" onClick={salvarCursos}>
              Salvar
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdmInfProf;
